commandLine.original:
python3 - <<'PY'
from pathlib import Path
import re, collections
files=[Path('dataset/run-001-normal/main.log'),Path('dataset/run-002-normal/main_2.log'),Path('dataset/run-003-normal/main_3.log'),Path('dataset/run-004-normal/main_4.log')]
terms=['block too old','Failed to verify sync info','OnLocalTimeout','OnRemoteTimeout','not enough timeouts','VoteRule: liveness condition failed','HighQC','DECIDE','Execute','CommitRule','Received proposal','CollectVote']
for p in files:
    lines=p.read_text(errors='replace').splitlines()
    print('\n===',p,'===')
    for t in terms:
        hit=[(i+1,s) for i,s in enumerate(lines) if t.lower() in s.lower()]
        print(f'{t}: {len(hit)}')
        if t in ['Execute','CommitRule'] and hit[:4]:
            for i,s in hit[:4]: print(' ',i,s[:240])
    print('--- messages potentially execution/commit ---')
    for i,s in enumerate(lines):
        if re.search(r'execute|executed|commit|decide',s,re.I):
            print(i+1,s[:260])
            if i>0 and i>250: break
PY

