from pathlib import Path
import re, collections
fs=[('R1','dataset/run-001-normal/main.log'),('R2','dataset/run-002-normal/main_2.log'),('R3','dataset/run-003-normal/main_3.log'),('R4','dataset/run-004-normal/main_4.log')]
for r,p in fs:
 L=Path(p).read_text(errors='replace').splitlines()
 pats=[('block too old',r'block too old'),('sync info fail',r'Failed to verify sync info'),('local timeout event',r'\bOnLocalTimeout$'),('local timeout payload',r'OnLocalTimeout:'),('remote timeout',r'OnRemoteTimeout \(advancing view\)'),('not enough timeouts',r'OnRemoteTimeout: not enough timeouts'),('liveness failed',r'VoteRule: liveness condition failed'),('HighQC updated',r'advanceView: Successfully updated HighQC'),('HighQC not updated',r'advanceView: HighQC not updated'),('advanceView calls',r'synchronizer/synchronizer.go:251\s+advanceView:'),('OnNewView',r'OnNewView'),('Commit',r'CommitRule - COMMIT'),('Decide',r'CommitRule - DECIDE'),('Execute block',r'consensus/committer.go:89\s+EXEC:'),('proposals received',r'Received proposal: Block\{'),('CollectVote messages',r'votingmachine/votingmachine.go:55\s+CollectVote\(from')]
 print(r,' '.join(f'{k}={sum(bool(re.search(pat,s)) for s in L)}' for k,pat in pats))
 print(' client:',[s for s in L if 'Done sending commands' in s][-1:])
 # distinct block views, missing proposals, proposer mismatches 0..1100
 views=set(); prop={}
 for s in L:
  m=re.search(r'Received proposal: Block\{ hash: (\S+) parent: .*? proposer: (\d+), view: (\d+)',s)
  if m: prop[int(m.group(3))]=int(m.group(2)); views.add(int(m.group(3)))
  m=re.search(r'OnRemoteTimeout \(advancing view\): ID: \d+, View: (\d+)',s)
  if m: views.add(int(m.group(1)))
 print('  proposal view missing in 0..1100:',[v for v in range(1101) if v not in prop][:20], 'count',sum(v not in prop for v in range(1101)))
 print('  proposer pattern deviations from 2,3,4,1:',[(v,p) for v,p in prop.items() if p != (v+1)%4+1][:12], 'n',sum(p != (v+1)%4+1 for v,p in prop.items()))
# example lines for stages in R1 and timeout scenario across runs
for r,p in fs:
 L=Path(p).read_text(errors='replace').splitlines()
 print('\n',r,'opening protocol lines 62-140')
 for n in range(62,min(140,len(L))):
  s=L[n]
  if re.search(r'Received proposal|advanceView: \{|HighQC|Verify|verified|Vote|CollectVote|OnNewView|PRE_COMMIT|COMMIT|DECIDE|EXEC:|On(Local|Remote)Timeout|not enough timeouts|new view',s,re.I): print(n+1,s)
PY

