  if m:P[m.group(1)]=(int(m.group(3)),int(m.group(2)))
 groups=collections.defaultdict(list)
 for s in L:
  m=re.search(r'\ths(\d+)\t.*?CollectVote\(from (\d+)\): (\S+)',s)
  if m:groups[(int(m.group(1)),m.group(3))].append(int(m.group(2)))
 full=[(k,v) for k,v in groups.items() if set(v)=={1,2,3,4}]
 dup=[(k,v) for k,v in groups.items() if len(v)>len(set(v))]
 hist=collections.Counter(tuple(sorted(set(v))) for v in groups.values())
 print(run,'receiver-block groups',len(groups),'full unique groups',len(full),'duplicate-containing groups',len(dup),'max messages per group',max(map(len,groups.values())),'unique sender sets',dict(hist))
 print('full first by receiver',dict(collections.Counter(k[0] for k,v in full)),'view samples',[(k[0],P.get(k[1]),v) for k,v in full[:3]])
