for run,path in fs:
 L=Path(path).read_text(errors='replace').splitlines(); P={}; orders=collections.defaultdict(list)
 for s in L:
  m=re.search(r'Received proposal: Block\{ hash: (\S+) parent: .*? proposer: (\d+), view: (\d+)',s)
  if m:P[m.group(1)]=(int(m.group(3)),int(m.group(2)))
 for s in L:
  m=re.search(r'\ths(\d+)\t.*?CollectVote\(from (\d+)\): (\S+)',s)
  if m:orders[(int(m.group(1)),m.group(3))].append(int(m.group(2)))
 byview={}
 for (recv,h),senders in orders.items():
  u=list(dict.fromkeys(senders))
  if len(u)==4:
   v,pr=P.get(h,(None,None))
   if v is not None:byview.setdefault(v,[]).append((recv,tuple(u)))
 D[run]=byview
 print(run,'complete views',len(byview),'multiple-complete-view entries',sum(len(x)>1 for x in byview.values()))
common=set.intersection(*(set(D[r]) for r,_ in fs))
common_single={v for v in common if all(len(D[r][v])==1 for r,_ in fs)}
identical_receiver={v for v in common_single if len({D[r][v][0][0] for r,_ in fs})==1}
identical_full={v for v in identical_receiver if len({D[r][v][0] for r,_ in fs})==1}
identical_order={v for v in common_single if len({D[r][v][0][1] for r,_ in fs})==1}
print('all four common complete views',len(common),'common single sequence each',len(common_single),'same receiver + order',len(identical_full),'same order any receiver',len(identical_order))
print('examples (view,receiver/order by run):',[(v,{r:D[r][v][0] for r,_ in fs}) for v in sorted(common_single)[:12]])
print('first disagreement sample:',[(v,{r:D[r][v][0] for r,_ in fs}) for v in sorted(common_single) if len({D[r][v][0][1] for r,_ in fs})>1][:8])
